import { APP_NAME } from '@gsm-app/constants';
import { buildControllerUrl, extractBeaconCode } from '@gsm-app/utils/buildControllerUrl';
import { Content } from '@gsm-common/components/Content';
import { createSuccess } from '@gsm-common/utils/toast/createSuccess';
import { IconCollapse, IconCopyCheckmark, IconExpand, IconX } from '@hawkins/assets';

import {
    useControllerBeacon,
} from '@ncgt/player';

import { Button, ContextualBanner, Loader, Text } from '@hawkins/components';
import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import styles from './Ssic.module.css';
const queryParams = new URLSearchParams(window.location.search);
const genClientId = () => (Math.random() + 1).toString(36).substring(7);

interface SsicFrameProps {
    url: string;
    clientId: string;
    removeFrame: (clientId: string) => void;
    popOutFrame: (clientId: string) => void;
    popInFrame: (clientId: string) => void;
    isPoppedOut: boolean;
}

const SsicFrame = memo(({ url, clientId, removeFrame, popOutFrame, popInFrame, isPoppedOut }: SsicFrameProps) => {
    const urlObj = new URL(url);
    const hashParams = new URLSearchParams(urlObj.hash.slice(1));
    hashParams.set('web', 'true');
    hashParams.set('clientId', `ncgt-${clientId}`);
    urlObj.hash = hashParams.toString();
    const ssicUrl = urlObj.toString();

    return (
        <div className={styles.frameContainer}>
            <div className={styles.frameHeader}>
                <Button
                    icon={IconX}
                    variant='icon'
                    compact
                    onClick={() => {
                        removeFrame(clientId);
                    }}
                >
                    Close Controller
                </Button>
                {!isPoppedOut ? (
                    <Button
                        icon={IconExpand}
                        variant='icon'
                        compact
                        onClick={() => {
                            popOutFrame(clientId);
                        }}
                    >
                        Open in New Window
                    </Button>
                ) : (
                    <Button
                        icon={IconCollapse}
                        variant='icon'
                        compact
                        onClick={() => {
                            popInFrame(clientId);
                        }}
                    >
                        Return Window
                    </Button>
                )}
                <Button
                    icon={IconCopyCheckmark}
                    variant='icon'
                    compact
                    onClick={() => {
                        navigator.clipboard.writeText(ssicUrl);
                        createSuccess({
                            title: 'Copied URL to clipboard',
                            options: {
                                duration: 1000,
                            },
                        });
                    }}
                >
                    Copy SSIC URL to Clipboard
                </Button>
                <Text className={styles.frameLabel}>Client ID: {clientId}</Text>
            </div>
            <div className={styles.frameBody}>
                {isPoppedOut ? (
                    <Button
                        icon={IconCollapse}
                        variant='icon'
                        onClick={() => {
                            popInFrame(clientId);
                        }}
                    >
                        Return Window
                    </Button>
                ) : (
                    <iframe title={`ncgt-${clientId}`} className={styles.frame} src={ssicUrl} />
                )}
            </div>
        </div>
    );
});

interface SsicWindowProps {
    url: string;
}

const SsicWindow = ({ url }: SsicWindowProps) => {
    const min: number = +(queryParams.get('min') ?? 1);
    const max: number = +(queryParams.get('max') ?? 4);

    const [clientIds, setClientIds] = useState<string[]>([...Array(min).keys()].map(() => genClientId()));
    const [poppedIds, setPoppedIds] = useState<string[]>([]);
    const poppedWindows = useRef<{ [key: string]: Window | null }>({});

    useEffect(() => {
        window.document.title = `${APP_NAME} - Controller`;

        const poppedWindowsTimer = window.setInterval(() => {
            for (const [clientId, poppedWindow] of Object.entries(poppedWindows.current)) {
                if (poppedWindow?.closed) {
                    popInFrame(clientId);
                }
            }
        }, 300);

        const closePoppedWindows = () => {
            for (const poppedWindow of Object.values(poppedWindows.current)) {
                poppedWindow?.close();
            }
        };
        window.addEventListener('beforeunload', closePoppedWindows);

        return () => {
            window.clearInterval(poppedWindowsTimer);
            window.removeEventListener('beforeunload', closePoppedWindows);
        };
    }, []);

    const popOutFrame = useCallback((clientId: string) => {
        const popoutParams = new URLSearchParams();
        popoutParams.set('url', url);
        popoutParams.set('popout', clientId);
        poppedWindows.current[clientId] = window.open(
            `/ssic?${popoutParams.toString()}`,
            `SSIC-${clientId}`,
            'width=500,height=300,left=0,top=0,popup',
        );
        setPoppedIds(prevItems => {
            return [...prevItems, clientId];
        });
    }, [url]);

    const popInFrame = useCallback((clientId: string) => {
        poppedWindows.current[clientId]?.close();
        delete poppedWindows.current[clientId];
        setPoppedIds(prevItems => prevItems.filter(id => id !== clientId));
    }, []);

    const removeFrame = useCallback((clientId: string) => {
        setClientIds(prevItems => prevItems.filter(id => id !== clientId));
    }, []);

    return (
        <>
            <div className={styles.container}>
                {clientIds.length ? (
                    clientIds.map(clientId => {
                        return (
                            <SsicFrame
                                key={clientId}
                                url={url}
                                clientId={clientId}
                                removeFrame={removeFrame}
                                popOutFrame={popOutFrame}
                                popInFrame={popInFrame}
                                isPoppedOut={poppedIds.includes(clientId)}
                            />
                        );
                    })
                ) : (
                    <div className={styles.emptyContainer}>
                        <Text>Add a controller to use the simulator</Text>
                    </div>
                )}
            </div>
            <Button
                variant='secondary'
                className={styles.addButton}
                disabled={clientIds.length >= max}
                onClick={() => {
                    if (clientIds.length < max) setClientIds([...clientIds, genClientId()]);
                }}
            >
                Add Controller
            </Button>
        </>
    );
};

interface SsicPopoutProps {
    url: string;
    clientId: string;
}

const SsicPopout = ({ url, clientId }: SsicPopoutProps) => {
    const urlObj = new URL(url);
    const hashParams = new URLSearchParams(urlObj.hash.slice(1));
    hashParams.set('web', 'true');
    hashParams.set('clientId', `ncgt-${clientId}`);
    urlObj.hash = hashParams.toString();
    const ssicUrl = urlObj.toString();

    return (
        <div className={styles.popoutContainer}>
            <div className={styles.frameContainer}>
                <div className={styles.frameHeader}>
                    <Text className={styles.frameLabel}>Client ID: {clientId}</Text>
                </div>
                <div className={styles.frameBody}>
                    <iframe title={`ncgt-${clientId}`} className={styles.frame} src={ssicUrl} />
                </div>
            </div>
        </div>
    );
};

export const Ssic = () => {
    const url: string = queryParams.get('url') ?? '';
    const popout: string | null = queryParams.get('popout');
    const urlOverride: string | null = queryParams.get('urlOverride');
    const passport: string = queryParams.get('passport') ?? '';
    const beaconEnabled: boolean = queryParams.get('beacon') === 'true';

    const [mutate, { error, data }] = useControllerBeacon({ passport });

    if (!url) {
        return <Content>Missing "url" param</Content>;
    }

    const beaconCode = useMemo(() => extractBeaconCode(url), [url])

    useEffect(() => {
        const getUrl = async () => {
            await mutate({ variables: { beaconCode } });
        }
        if (beaconEnabled && beaconCode && passport) {
            getUrl();
        }
    }, [beaconEnabled, beaconCode, mutate, passport]);

    if (data?.ngpRedeemBeacon?.__typename === 'NGPRedeemBeaconFailed') {
        return (
            <ContextualBanner variant='error' title='Error' text={data?.ngpRedeemBeacon?.reason || 'Could not open controller'} />
        );
    }

    if (!beaconEnabled) {
        return <>{popout ? <SsicPopout url={url} clientId={popout} /> : <SsicWindow url={url} />}</>;
    }

    const controllerUiUrl = urlOverride || data?.ngpRedeemBeacon?.controllerUiUrl;
    const connectionUrl = data?.ngpRedeemBeacon?.connectionUrl || '';
    const gameplaySessionId = data?.ngpRedeemBeacon?.gameplaySessionId || '';
    const gameId = data?.ngpRedeemBeacon?.gameId;
    const connectionSecret = data?.ngpRedeemBeacon?.connectionSecret || '';
    const controllerUiParameters: { key: string, value: string }[] = data?.ngpRedeemBeacon?.controllerUiParameters || [];

    if (!controllerUiUrl) {
        return <Loader variant='linear' />
    } else if (error) {
        return <ContextualBanner variant='error' text={JSON.stringify(error)} />
    } else {

        const fullUrl = buildControllerUrl({ controllerUiUrl, gameId, gameplaySessionId, connectionSecret, connectionUrl, controllerUiParameters });

        if (popout) {
            return (
                <SsicPopout url={fullUrl} clientId={popout} />
            );
        } else {
            return (
                <SsicWindow url={fullUrl} />
            );
        }
    }
};
